function check(string $name,bool $ok,string $detail=''): void {
 global $results;
 $results[]=['name'=>$name,'pass'=>$ok,'detail'=>$detail];
 echo ($ok?'PASS':'FAIL').' | '.$name.($detail!==''?' | '.$detail:'').PHP_EOL;
}
class Client {
 public string $cookie;public string $token='';
 public function __construct(public string $base){$this->cookie=tempnam(sys_get_temp_dir(),'cms-qa-');}
 public function __destruct(){if(is_file($this->cookie))unlink($this->cookie);}
 public function request(string $route='',array $query=[],?array $data=null,bool $csrf=true):array{
  $address=$this->base.'index.php?'.http_build_query(['r'=>$route]+$query);
  $ch=curl_init($address);
  $options=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEFILE=>$this->cookie,CURLOPT_COOKIEJAR=>$this->cookie,CURLOPT_TIMEOUT=>20,CURLOPT_FOLLOWLOCATION=>false];
  if($data!==null){if($csrf)$data['_csrf']=$this->token;$options[CURLOPT_POST]=true;$options[CURLOPT_POSTFIELDS]=$data;}
  curl_setopt_array($ch,$options);$raw=curl_exec($ch);
  if($raw===false)throw new RuntimeException(curl_error($ch));
  $status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$n=curl_getinfo($ch,CURLINFO_HEADER_SIZE);$headers=substr($raw,0,$n);$body=substr($raw,$n);curl_close($ch);
  if(preg_match('/name="_csrf" value="([^"]+)"/',$body,$m))$this->token=html_entity_decode($m[1]);
  preg_match('/^Location:\s*(.+)$/mi',$headers,$location);
  return ['status'=>$status,'body'=>$body,'headers'=>$headers,'location'=>trim($location[1]??'')];
 }
 public function login(string $email,string $password='Demo@12345'):array{
  $this->request('login');$r=$this->request('login',[],['email'=>$email,'password'=>$password]);$this->request('profile');return $r;
 }
}
