$md="# Kết quả kiểm thử HTTP + MariaDB\n\nThời điểm: ".$report['finished_at']."\n\nURL: $base\n\nDatabase riêng: news_blog_cms_test. Không chạy thao tác nghiệm thu trên database demo chính.\n\n**".$report['passed']." PASS / ".$report['failed']." FAIL**\n\n| # | Ca kiểm thử | Kết quả | Ghi chú |\n|---|---|---|---|\n";
foreach($results as $i=>$t)$md.='| '.($i+1).' | '.$t['name'].' | '.($t['pass']?'PASS':'FAIL').' | '.str_replace('|','/',$t['detail'])." |\n";
file_put_contents(ROOT.'/docs/TEST-RESULTS.md',$md);
echo "\n".$report['passed']." passed, ".$report['failed']." failed\n";
exit($report['failed']?1:0);
